//! pleme-io typed wrapper — auto-generated by caixa-forge.
//!
//! Typed shapes live under `providers/aws/*.tlisp`, generated by lava-forge
//! from the `hashicorp/aws` 6.69.1 provider schema (`terraform providers
//! schema -json`). The DNS and edge shapes below are the full schema; the
//! older shapes are short hand-kept subsets.

#[cfg(test)]
mod tests {
    use std::path::Path;

    fn shape(name: &str) -> String {
        std::fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("providers/aws")
                .join(format!("{name}.tlisp")),
        )
        .unwrap_or_else(|e| panic!("{name}: {e}"))
    }

    #[test]
    fn smoke() {
        assert_eq!(2 + 2, 4);
    }

    #[test]
    fn dns_and_edge_shapes_are_indexed() {
        let index = shape("_index");
        for kw in [
            ":aws-route53-zone",
            ":aws-route53-record",
            ":aws-acm-certificate",
            ":aws-acm-certificate-validation",
            ":aws-cloudfront-distribution",
        ] {
            assert!(index.contains(kw), "{kw} missing from _index");
        }
    }

    #[test]
    fn dns_and_edge_shapes_declare_their_required_attributes() {
        let cases: &[(&str, &str, &[&str])] = &[
            ("aws_route53_zone", ":aws-route53-zone", &["(:name"]),
            (
                "aws_route53_record",
                ":aws-route53-record",
                &["(:zone-id", "(:name", "(:type", "(:records", "(:ttl", "(:alias"],
            ),
            (
                "aws_acm_certificate",
                ":aws-acm-certificate",
                &["(:domain-name", "(:validation-method", "(:subject-alternative-names", "(:domain-validation-options"],
            ),
            (
                "aws_acm_certificate_validation",
                ":aws-acm-certificate-validation",
                &["(:certificate-arn", "(:validation-record-fqdns"],
            ),
            (
                "aws_cloudfront_distribution",
                ":aws-cloudfront-distribution",
                &["(:enabled", "(:aliases", "(:is-ipv6-enabled", ":nested-blocks", "(:origin", "(:default-cache-behavior", "(:viewer-certificate", "(:restrictions"],
            ),
        ];
        for (file, head, attrs) in cases {
            let body = shape(file);
            assert!(body.contains(head), "{file}: head {head}");
            for a in *attrs {
                assert!(body.contains(a), "{file}: missing {a}");
            }
        }
    }

    #[test]
    fn cloudfront_nested_blocks_carry_their_bodies() {
        let body = shape("aws_cloudfront_distribution");
        for a in [":origin-path", ":custom-origin-config", ":cache-policy-id", ":acm-certificate-arn", ":restriction-type"] {
            assert!(body.contains(a), "missing {a}");
        }
    }
}
